"""Render completed full-recording pilot evidence, no API calls."""
import json
from collections import Counter
from full_recording_experiment import DATA,RUN,ROOT,CONDITIONS,CLASSES,read_lines

def main():
    e=json.loads((RUN/'evaluation.json').read_text());truth=json.loads((DATA/'truth.json').read_text());rows=read_lines(RUN/'responses.jsonl');review=read_lines(RUN/'explanation_review.jsonl');meta=json.loads((DATA/'manifest.json').read_text());probe=json.loads((RUN/'preflight.json').read_text())
    pct=lambda x:f'{x*100:.2f}%';fmt=lambda x:'NA' if x is None else f'{x:.3f}'
    lines=['# Full-recording direct privacy inference: C1–C5 results','',
    '## Scope and technical verification','',
    f'Executed {len(rows)} requests on the frozen 14 right-pocket recordings from development users 8–9. Seven labeled references come from training users 1–7, using the selections in full_recording_prompt_audit.md. These participants are absent from the reference set but are repeatedly inspected development users, not an untouched final test. No fine-tuning, external classifier-generated Qwen prediction, tool use, feedback, reference selection by performance, or evaluation expansion occurred.', '',
    'Each request has one fixed system message and one user message. The full original proposed bit-string payloads were reused unchanged. Every serialized character was decoded and compared with the corresponding CSV binary sample in order. Targets contain only observation_extent and binary_sequence; references additionally contain their authorized activity label. Filenames, subject IDs, target labels and offsets are absent. Full files include every sample, with no padding, resampling, truncation, cross-file joins or run-length encoding. Extents are explicitly marked complete recordings or excerpts. Exact saved messages are in data/full-recording-screen/requests.jsonl and copied into response logs.', '',
    'Provider was restricted to the exact deepinfra/fp8 endpoint, with allow_fallbacks=false and require_parameters=true. This follows the documented [OpenRouter routing controls](https://openrouter.ai/docs/guides/routing/provider-selection). Fresh endpoint metadata advertised 262,144 context tokens and the required parameters. All cells used qwen/qwen3.5-35b-a3b, temperature 0.1, max_tokens 600, reasoning disabled and JSON-object output with the existing strict local five-field validator. No sampling seed is assumed. Submission order used seed 47 and a counterbalanced rotation; the first planned C4 request was moved to the beginning as the feasibility gate. Remaining calls used two concurrent workers and a 180-second timeout, with no retries.', '',
    f'The largest local content count was 92,325 tokens; including a 1,024-token framing reserve and 600 output tokens gives 93,949, below the advertised context. First C4 request `{probe["id"]}` returned {probe["status"]} from {probe["provider"]}, with {probe["usage"]["prompt_tokens"]:,} input tokens and {probe["usage"]["completion_tokens"]} output tokens. It is included in the 70, not an extra probe.', '',
    f'Returned providers: {dict(Counter(r.get("returned_provider") for r in rows))}. Reported input counts minus locally tokenized content counts: {sorted({r["usage"]["prompt_tokens"]-r["local_content_tokens"] for r in rows if r.get("usage")})}. This agreement and the saved source-verified payloads support complete submission; provider-internal processing and attention cannot be directly inspected. A valid response does not prove that Qwen examined every bit.', '',
    '## Matched conditions','', '| Cell | Target | Same seven reference recordings |','|---|---|---|',
    '| C1 | Saved E2 100-sample excerpt | First 100 samples each |',
    '| C2 | Same 100-sample excerpt | Complete files |',
    '| C3 | Complete file | First 100 samples each |',
    '| C4 | Complete file | Complete files |',
    '| C5 | First 500 samples, marked excerpt | Complete files |','',
    'Every cell predicts the dataset-assigned activity of the same recording. Short excerpts do not use hidden internal activity boundaries. All evaluation files are constant, so C5’s different excerpt position does not change bit content. Full references total 76,770 samples; only the selected Standing reference varies, with transitions at samples 6500, 6550, 10450 and 10500. That reference has 100 positive samples in 14,995, embedded in two short bursts. Its first 100 samples are zero. Reference participant and class are confounded in this small one-reference-per-class panel.', '',
    '## Results','', '| Cell | Valid / 14 | Accuracy | Balanced accuracy | Macro-F1 | Motion-group accuracy | Mean confidence | Insufficient information |','|---|---:|---:|---:|---:|---:|---:|---:|']
    for c in CONDITIONS:
        v=e['conditions'][c];lines.append(f'| {c} | {v["status_counts"].get("valid",0)}/14 | {pct(v["accuracy"])} | {pct(v["balanced_accuracy"])} | {v["macro_f1"]:.5f} | {pct(v["moving_stationary_accuracy"])} | {fmt(v["mean_confidence"])} | {pct(v["insufficient_fraction"]) if v["insufficient_fraction"] is not None else "NA"} |')
    lines+=['','Invalid/missing predictions count as errors in all-target scores. Confidence and uncertainty summaries use valid outputs only. Macro-F1 is computed across all seven labels.','', '| Paired contrast | Accuracy difference (pp) | Changed outputs | Wrong→correct | Correct→wrong | Valid pairs |','|---|---:|---:|---:|---:|---:|']
    for k,v in e['contrasts'].items():lines.append(f'| {k} | {100*v["accuracy_difference"]:+.2f} | {v["changes"]} | {v["wrong_to_correct"]} | {v["correct_to_wrong"]} | {v["valid_pair_n"]} |')
    lines+=['','Matched valid-pair accuracy differences: '+ '; '.join(k+': '+format(v['valid_pair_accuracy_difference']*100,'+.2f')+' pp (n='+str(v['valid_pair_n'])+')' for k,v in e['contrasts'].items() if v['valid_pair_accuracy_difference'] is not None)+'.']
    lines+=['','C2−C1 and C4−C3 assess reference extent at fixed target access. C3−C1 and C4−C2 assess target extent at fixed references. C4−C5 compares natural-length targets with fixed 500-sample targets at full reference access. C5−C2 changes only the amount of redundant constant target samples, extent wording stays excerpt. No contrast alone identifies the effect of temporal order.','', '## Duration baselines and input ambiguity','',
    'Primary baselines receive exactly the seven reference observations and target extent exposed in each cell. Duration-only chooses the reference closest in sample count; binary-plus-duration first restricts to matching majority bit, then chooses closest count. Ties use the fixed candidate-class order. The fixed bit rule selects Walking for mostly ones and Sitting otherwise. These are deterministic offline comparators, not sources of Qwen predictions. Baselines were frozen before inference; none use evaluation-label fitting.', '', '| Cell | Duration-only | Binary + duration | Fixed bit | Unique full prompts | Empirical pattern bound |','|---|---:|---:|---:|---:|---:|']
    for c in CONDITIONS:
        v=e['conditions'][c];lines.append(f'| {c} | {pct(v["baselines"]["duration_only"]["accuracy"])} | {pct(v["baselines"]["binary_plus_duration"]["accuracy"])} | {pct(v["baselines"]["fixed_bit"]["accuracy"])} | {v["unique_inputs"]} | {pct(v["pattern_bound"])} |')
    lines+=['','Full-training diagnostic baselines additionally use all 147 training files (greater reference access than Qwen), selecting nearest sample count and lexicographic source-path tie-break. They are descriptive comparisons, not access-matched primary baselines:']
    for name,v in e['full_training_length_diagnostics'].items():lines.append(f'- {name}: {pct(v["accuracy"])} accuracy, {v["macro_f1"]:.5f} macro-F1.')
    lines+=['','For complete evaluation files, the full binary sequence is determined exactly by its bit value and sample count. Thus all added target distinctions are length distinctions; there are no target transition patterns to exploit. Stair files are much shorter than approximately five-minute non-stair files, and tiny export-length differences can act as acquisition fingerprints. The 13/14 natural-length empirical bound uses hidden evaluator labels and mostly rare length signatures; it is not a deployable attacker score or evidence of generalization. Fixed-length C1/C2/C5 have only two observable input groups and a 4/14 deterministic mapping bound. Stochastic guesses may exceed that bound in one realization without acquiring distinguishing information.', '',
    '## Confidence and explanations','', '| Cell | Confidence correct | Confidence wrong | Wrong confidence ≥0.8 | Flagged / reviewed valid explanations |','|---|---:|---:|---:|---:|']
    for c in CONDITIONS:
        v=e['conditions'][c];rr=[r for r in review if r['condition']==c and r['status']=='valid' and r['unsupported'] is not None];lines.append(f'| {c} | {fmt(v["confidence_correct"])} | {fmt(v["confidence_wrong"])} | {v["high_confidence_errors"]} | {sum(r["unsupported"] for r in rr)}/{len(rr)} |')
    lines+=['','Review is a provisional qualitative assessment by the implementation assistant, not an independent human-validated annotation. The review sheet excludes hidden labels/correctness, but the reviewer has seen aggregate results; it is not fully blind. No additional judge API was called. Claims of rhythm/intensity from constant outputs, invented counts, false differences between references, and conflating length with physical dynamics are flagged. Merely making an explicitly uncertain forced choice is not automatically flagged. Human review and agreement are required before publication.','', '## Individual predictions','', '| Target | Subject | True activity | Samples | C1 | C2 | C3 | C4 | C5 |','|---|---:|---|---:|---|---|---|---|---|']
    for i,t in enumerate(truth):lines.append('| '+ ' | '.join([t['id'],str(t['subject']),t['activity'],str(t['samples'])]+[e['conditions'][c]['predictions'][i] for c in CONDITIONS])+' |')
    lines+=['','Ground truth in this evaluator table was never included in target prompts. The complete provenance, including source hashes and excerpt offsets, is in the frozen manifest.','', '## Confusion matrices and subject results','','Rows: '+', '.join(CLASSES)+'. Columns: same order plus INVALID_OR_MISSING.']
    for c in CONDITIONS:
        v=e['conditions'][c];matrix=v['confusion_matrix'];recall={CLASSES[i]:matrix[i][i]/sum(matrix[i]) for i in range(7)}
        lines+=['','### '+c,'','```json',json.dumps({'matrix':matrix,'per_class_recall':recall,'subject_accuracy':{s:d['accuracy'] for s,d in v['by_subject'].items()}}),'```']
    lines+=['','## Cost, failures and runtime','', '| Cell | Input tokens | Output tokens | Reported USD | Cost / valid |','|---|---:|---:|---:|---:|']
    for c in CONDITIONS:
        v=e['conditions'][c];u=v['usage'];n=v['status_counts'].get('valid',0);lines.append(f'| {c} | {u["prompt_tokens"]:,} | {u["completion_tokens"]:,} | ${u["cost"]:.6f} | {"$"+format(u["cost"]/n,".6f") if n else "NA"} |')
    total=sum(v['usage']['cost'] for v in e['conditions'].values());wall=json.loads((RUN/'runtime.json').read_text())['wall_seconds']
    lines+=['',f'Total reported cost ${total:.6f}; wall runtime {wall:.1f} seconds. Calls: {len(rows)}. Returned finish reasons: {dict(Counter(r.get("finish_reason") for r in rows))}. No retries or discarded attempts.']
    failures=[r for r in rows if r['status']!='valid']
    lines += [f'- {r["id"]}: {r["status"]}, finish={r.get("finish_reason")}, error={r.get("error")}' for r in failures] or ['All responses passed the fixed schema.']
    lines+=['','## Interpretation and next experiment','',(ROOT/'reports/full_recording_interpretation.md').read_text(),'','## Reproduction and preservation','','Frozen inputs/settings: data/full-recording-screen. Raw responses, first-request gate, timing, evaluations and explanation annotations: runs/full-recording-screen. Prior experiment files and audit artifacts are hash-checked against preservation.json. No existing experiment was rewritten. Credentials and data/run directories remain Git-ignored. Exact prompt templates are unchanged from reports/full_recording_prompt_audit.md; all sent messages are saved.','','```bash\n# Offline analysis only; neither command submits requests.\n.venv/bin/python full_recording_experiment.py evaluate\n.venv/bin/python full_recording_report.py\n```','','The runner rejects an existing run directory and does not retry automatically. The evaluator preserves existing review annotations. New submissions require a separate, explicitly scoped experiment.']
    (ROOT/'reports/full_recording_inference_results.md').write_text('\n'.join(lines)+'\n')
if __name__=='__main__':main()
